import React, { useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import api from '../api/axios';
import { Container, Table, Spinner, Alert, Form, Button } from 'react-bootstrap';

const Schedule = () => {
  const [schedule, setSchedule] = useState([]);
  const [classes, setClasses] = useState([]);
  const [selectedClass, setSelectedClass] = useState('');
  const [weekStart, setWeekStart] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const roles = useSelector(state => state.auth.roles || []);
  const isDirector = roles.includes('Директор');

  useEffect(() => {
    // Загружаем классы для фильтра
    if (isDirector) {
      api.get('/director/classes').then(res => {
        setClasses(res.data);
      }).catch(console.error);
    }
    // Устанавливаем начало текущей недели
    const now = new Date();
    const day = now.getDay();
    const diff = now.getDate() - day + (day === 0 ? -6 : 1);
    const monday = new Date(now.setDate(diff));
    setWeekStart(monday.toISOString().split('T')[0]);
  }, []);

  useEffect(() => {
    if (weekStart) {
      fetchSchedule();
    }
  }, [weekStart, selectedClass]);

  const fetchSchedule = async () => {
    setLoading(true);
    setError('');
    try {
      const params = { week: weekStart };
      if (selectedClass) {
        params.class_id = selectedClass;
      }
      const res = await api.get('/schedule', { params });
      setSchedule(res.data.schedule || []);
    } catch (err) {
      setError(err.response?.data?.error || 'Ошибка загрузки расписания');
    } finally {
      setLoading(false);
    }
  };

  const weekDays = ['ПН', 'ВТ', 'СР', 'ЧТ', 'ПТ', 'СБ', 'ВС'];

  // Функция получения дня недели по дате (0 = понедельник)
const getDayIndex = (dateStr) => {
  const date = new Date(dateStr);
  let day = date.getDay(); // 0 = воскресенье
  return day === 0 ? 6 : day - 1; // воскресенье -> 6, понедельник -> 0
};

  const getDaySchedule = (dayIndex) => {
    const date = new Date(weekStart);
date.setDate(date.getDate() + dayIndex);
const dateStr = date.toISOString().split('T')[0];
return schedule.filter(item => item.date === dateStr).sort((a, b) => a.lesson_number - b.lesson_number);
};

  const changeWeek = (delta) => {
    const date = new Date(weekStart);
    date.setDate(date.getDate() + delta * 7);
    setWeekStart(date.toISOString().split('T')[0]);
  };

  if (loading) {
    return (
      <Container className="text-center mt-5">
        <Spinner animation="border" variant="primary" />
        <p>Загрузка расписания...</p>
      </Container>
    );
  }

  if (error) {
    return (
      <Container className="mt-4">
        <h3>Расписание</h3>
        <Alert variant="danger">{error}</Alert>
      </Container>
    );
  }

  return (
    <Container className="mt-4">
      <h3 style={{ textAlign: 'center' }}>Расписание на неделю</h3>
      
      <div className="d-flex justify-content-between align-items-center mb-3">
        <Button variant="outline-secondary" onClick={() => changeWeek(-1)}>← Предыдущая</Button>
        <span style={{ fontWeight: 'bold' }}>
          {weekStart ? new Date(weekStart).toLocaleDateString('ru-RU', { day: '2-digit', month: '2-digit', year: 'numeric' }) : ''}
        </span>
        <Button variant="outline-secondary" onClick={() => changeWeek(1)}>Следующая →</Button>
      </div>
      
      {isDirector && (
        <div className="mb-3">
          <Form.Select 
            value={selectedClass} 
            onChange={e => setSelectedClass(e.target.value)}
          >
            <option value="">Выберите класс</option>
            {classes.map(c => (
              <option key={c.id} value={c.id}>{c.grade} класс</option>
            ))}
          </Form.Select>
        </div>
      )}
      
      {schedule.length === 0 ? (
        <Alert variant="info">Нет уроков на эту неделю</Alert>
      ) : (
        <div className="table-responsive">
          <Table bordered hover>
            <thead>
              <tr>
                <th>Время</th>
                {weekDays.map((day, i) => (
                  <th key={i}>
                    {day}
                    <br />
                    <small>
                      {weekStart ? new Date(new Date(weekStart).setDate(new Date(weekStart).getDate() + i)).toLocaleDateString('ru-RU', { day: '2-digit', month: '2-digit' }) : ''}
                    </small>
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {[1,2,3,4,5,6,7,8].map(lessonNum => (
                <tr key={lessonNum}>
                  <td style={{ fontWeight: 'bold' }}>{lessonNum}</td>
                  {weekDays.map((_, dayIndex) => {
                    const lessons = getDaySchedule(dayIndex);
                    const lesson = lessons.find(l => l.lesson_number === lessonNum);
                    return (
                      <td key={`${dayIndex}-${lessonNum}`}>
                        {lesson ? (
                          <>
                            <strong>{lesson.subject_name}</strong>
                            <br />
                            <small>{lesson.teacher_name}</small>
                            <br />
                            <small className="text-muted">ДЗ: {lesson.homework || '—'}</small>
                          </>
                        ) : (
                          <span className="text-muted">—</span>
                        )}
                      </td>
                    );
                  })}
                </tr>
              ))}
            </tbody>
          </Table>
        </div>
      )}
    </Container>
  );
};

export default Schedule;
